/* @lc app=leetcode id=2858 lang=kotlin */
class Solution { fun minEdgeReversals(n: Int, edges: Array<IntArray>): IntArray = Array(n) { mutableListOf<Pair<Int, Int>>() }.apply { edges.forEach { (u, v) -> this[u].add(v to 0).run { this@apply[v].add(u to 1) } } }.let { adj -> IntArray(n).apply { this.set(0, kotlin.DeepRecursiveFunction<Pair<Int, Int>, Int> { (u, p) -> adj[u].filter { it.first != p }.sumOf { (v, cost) -> cost + callRecursive(v to u) } }.call(0 to -1)).run { kotlin.DeepRecursiveFunction<Triple<Int, Int, Int>, Unit> { (u, p, cur) -> this@apply.set(u, cur).also { adj[u].filter { it.first != p }.forEach { (v, cost) -> callRecursive(Triple(v, u, cur + if (cost == 0) 1 else -1)) } } }.call(Triple(0, -1, this@apply[0])) } } } }